import {createWorld} from './world.js';
'use strict';
const $=id=>document.getElementById(id),canvas=$('scene'),world=createWorld(canvas);
const KEY='roadster-flight-v1';let records=[],storageOK=true,view='rank',playerName='';
try{const data=JSON.parse(localStorage.getItem(KEY)||'{}');records=Array.isArray(data.records)?data.records.filter(r=>r&&typeof r.name==='string'&&Number.isFinite(r.distance)&&r.distance>=0).slice(0,100):[];playerName=typeof data.name==='string'?data.name:'';}catch{storageOK=false;}
$('player').value=playerName;
const input={up:false,down:false,boost:false};let state='ready',paused=false,accumulator=0,last=0,simTime=0,flight=null,W=900,H=490,scale=5,camX=0,camY=0;
for(let i=0;i<10;i++)$('fuel').appendChild(document.createElement('b'));
function persist(){try{localStorage.setItem(KEY,JSON.stringify({name:playerName,records}));}catch{storageOK=false;}$('storageNote').textContent=storageOK?'名称与成绩仅保存在此浏览器。以首次触地的水平距离计分，非全球榜单。':'浏览器未允许保存，当前记录仅在本次页面有效。';}
function renderRecords(){const sorted=view==='rank'?[...records].sort((a,b)=>b.distance-a.distance):records;const best=[...records].sort((a,b)=>b.distance-a.distance)[0];$('best').textContent=best?best.distance.toFixed(1):'—';$('bestName').textContent=best?best.name+' · '+new Date(best.time).toLocaleDateString('zh-CN'):'等待第一位驾驶员';$('runCount').textContent=String(records.length).padStart(2,'0');$('records').replaceChildren();if(!sorted.length){const e=document.createElement('div');e.className='empty';e.textContent='还没有飞行记录。你的第一次飞跃，将从这里开始。';$('records').append(e);}sorted.slice(0,5).forEach((r,i)=>{const row=document.createElement('div');row.className='row';for(const [tag,text]of [['span',String(i+1).padStart(2,'0')],['b',r.name],['strong',r.distance.toFixed(1)+' m']]){const e=document.createElement(tag);e.textContent=text;row.append(e);}$('records').append(row);});}
function clearInput(){for(const k in input){input[k]=false;$(k).classList.remove('pressed');}}
function setPause(p){if(!['run','flight'].includes(state))return;paused=p;$('pauseFlag').hidden=!p;clearInput();$('pause').textContent=p?'继续':'暂停';$('phase').textContent=p?'FLIGHT PAUSED':state==='run'?'ACCELERATING':'FLIGHT IN PROGRESS';}
function start(){if(!world.ready)return;playerName=$('player').value.trim();if(!playerName){$('message').textContent='请输入驾驶员名称';$('player').focus();return;}$('message').textContent='';$('player').blur();persist();flight={x:-85,y:1.2,vx:0,vy:0,a:0,av:0,fuel:100,t:0,distance:0};state='run';paused=false;$('pauseFlag').hidden=true;simTime=0;accumulator=0;clearInput();$('pause').textContent='暂停';$('overlay').classList.add('hidden');$('phase').textContent='ACCELERATING';}
function finish(){state='end';clearInput();const distance=Math.max(0,Math.round(flight.x*10)/10),best=Math.max(0,...records.map(r=>r.distance));records.unshift({name:playerName,distance,time:Date.now(),landing:Math.abs(flight.a)<.4?'smooth':'rough'});records=records.slice(0,100);persist();renderRecords();$('cardEyebrow').textContent=distance>best?'NEW PERSONAL RECORD':'FLIGHT COMPLETED';$('cardTitle').textContent=distance.toFixed(1)+' 米';$('cardText').textContent=(Math.abs(flight.a)<.4?'平稳触地。':'触地时车身倾斜，下次试着提前调平。')+' 已记录本次飞行，再挑战一次？';$('startButton').textContent='再飞一次 ↗';$('overlay').classList.remove('hidden','ready-screen');$('phase').textContent='FLIGHT COMPLETED';}
function step(dt){if(paused||!flight||!['run','flight'].includes(state))return;simTime+=dt;const f=flight;f.t+=dt;if(state==='run'){f.vx=Math.min(43,f.vx+23*dt);f.x+=f.vx*dt;f.y=f.x>-28?1.2+(f.x+28)*.36:1.2;f.a=f.x>-28?.346:0;if(f.x>=0){f.x=0;f.y=11.3;f.vx=40;f.vy=17;f.a=.4;state='flight';$('phase').textContent='FLIGHT IN PROGRESS';}return;}
const turn=(input.up?1:0)-(input.down?1:0);f.av+=(turn*2.8-f.av*3.5)*dt;f.a=Math.max(-1.2,Math.min(1.45,f.a+f.av*dt));let thrust=0;if(input.boost&&f.fuel>0){const used=Math.min(f.fuel,100/6*dt);thrust=used/(100/6*dt)*19;f.fuel-=used;}
const speed=Math.hypot(f.vx,f.vy),track=Math.atan2(f.vy,f.vx),aoa=f.a-track;const lift=Math.max(-7,Math.min(12,speed*speed*.008*Math.sin(2*aoa)));const drag=.0009*speed*(1+6*Math.sin(aoa)**2);f.vx+=(thrust*(Math.cos(f.a)-.3*Math.sin(f.a))-drag*f.vx-lift*Math.sin(track))*dt;f.vy+=(thrust*(Math.sin(f.a)+.3*Math.cos(f.a))-9.81-drag*f.vy+lift*Math.cos(track))*dt;f.x+=Math.max(0,f.vx)*dt;f.y+=f.vy*dt;f.distance=f.x;if(f.y<=1.05){f.y=1.05;finish();}}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;world.resize(W,H);}
function draw(){const f=flight||{x:-45,y:1.05,a:0,fuel:100,vx:0,vy:0};world.update(f,state,state==='flight'&&!paused&&input.boost&&f.fuel>0,paused,simTime);$('distance').textContent=(f.distance||0).toFixed(1);$('fuelLabel').textContent=Math.ceil(f.fuel)+'%';[...$('fuel').children].forEach((el,i)=>el.style.background=f.fuel>i*10?'#ed413b':'#343139');$('height').textContent=Math.max(0,f.y-1.05).toFixed(1);$('speed').textContent=Math.round(Math.hypot(f.vx,f.vy)*3.6);$('pitch').textContent=Math.round(f.a*180/Math.PI);}
function frame(t){if(!last)last=t;accumulator+=Math.min((t-last)/1000,.08);last=t;while(accumulator>=1/120){step(1/120);accumulator-=1/120;}draw();requestAnimationFrame(frame);}
for(const key of ['up','down','boost']){const el=$(key);el.addEventListener('pointerdown',e=>{e.preventDefault();if(paused)return;input[key]=true;el.classList.add('pressed');el.setPointerCapture(e.pointerId);});for(const type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,()=>{input[key]=false;el.classList.remove('pressed');});}
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName)||$('helpDialog').open)return;const k={ArrowLeft:'down',ArrowRight:'up',Space:'boost'}[e.code];if(k){e.preventDefault();if(!paused){input[k]=true;$(k).classList.add('pressed');}}if(e.code==='KeyP'&&!e.repeat)setPause(!paused);});document.addEventListener('keyup',e=>{const k={ArrowLeft:'down',ArrowRight:'up',Space:'boost'}[e.code];if(k){input[k]=false;$(k).classList.remove('pressed');}});window.addEventListener('blur',()=>{clearInput();setPause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden)setPause(true);});$('pause').onclick=()=>setPause(!paused);$('startForm').onsubmit=e=>{e.preventDefault();start();};$('rankTab').onclick=()=>{view='rank';$('rankTab').classList.add('active');$('recentTab').classList.remove('active');renderRecords();};$('recentTab').onclick=()=>{view='recent';$('recentTab').classList.add('active');$('rankTab').classList.remove('active');renderRecords();};$('help').onclick=()=>{setPause(true);$('helpDialog').showModal();};$('closeHelp').onclick=()=>$('helpDialog').close();new ResizeObserver(resize).observe(canvas);renderRecords();persist();resize();requestAnimationFrame(frame);
